const repos = $input.all().map(i => i.json);
const cibles = repos.filter(r => !r.archived && !r.description && !r.fork);
return cibles.map(r => ({
  json: {
    name: r.name,
    full_name: r.full_name,
    language: r.language || "",
    prompt: "Tu écris des descriptions courtes de projets GitHub. Exemples du style attendu :\n- « Suivi de chantier pour petites équipes »\n- « Portfolio de photographie argentique »\n- « Veille automatique des prix concurrents »\nProjet à décrire : « " + r.name + " » (langage : " + (r.language || "inconnu") + "). Écris une description en français, une seule ligne, maximum 60 caractères, sans guillemets. Réponds uniquement par la description, rien d'autre."
  }
}));

// Mode par item : $('Filtre').item résout le BON item (fix pairing du 16/09)
const src = $('Filtre — sans description').item.json;
let d = (($json.response || '').trim().split('\n').filter(Boolean)[0] || '').trim();
d = d.replace(/^[\-\*«»"'\s]+/, '').replace(/[«»"'\s]+$/, '').replace(/\*\*/g, '').trim();
if (d.length > 80) d = d.slice(0, 77).trim() + '…';
if (!d) d = 'Projet ' + src.name + (src.language ? ' (' + src.language + ')' : '');
return { json: { full_name: src.full_name, name: src.name, description: d } };

const items = $input.all();
if (!items.length) return [];
const lignes = items.map(i => '- ' + i.json.name + ' : ' + i.json.description).join('\n');
return [{ json: { text: '🏷️ Descriptions GitHub ajoutées (' + items.length + ') :\n' + lignes } }];

// ===== Dépendances hebdo — vérifie les mises à jour, crée branche + Pull Request =====
// Exécute le lundi 22h00 (Paris). Ne touche JAMAIS à main : une branche deps/maj-auto-<date>
// est créée avec un commit de mise à jour des dépendances, puis une PR est ouverte automatiquement.
const CONFIG = {
  githubToken: 'Bearer github_pat_MASQUE',
  maxPkgsParRepo: 40,     // plafond de paquets vérifiés par repo
  maxDetail: 6,           // lignes de détail max par repo dans le récap Telegram
};

const H = {
  Authorization: CONFIG.githubToken,
  'User-Agent': 'n8n-deps-weekly',
  'X-GitHub-Api-Version': '2022-11-28',
  Accept: 'application/vnd.github+json',
};
const API = 'https://api.github.com';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const req = (opts) => this.helpers.httpRequest({ headers: H, ...opts });
// httpRequest peut auto-parser les réponses JSON même avec json:false → normaliser en texte
const getTexte = (raw) => typeof raw === 'string'
  ? raw
  : (raw && typeof raw.body === 'string' ? raw.body : JSON.stringify(raw && raw.body !== undefined ? raw.body : raw, null, 2));

// --- versions ---
const pad = (v) => v.split('.').map((x) => parseInt(x, 10) || 0);
const cmp = (a, b) => {
  const A = pad(a), B = pad(b);
  for (let i = 0; i < Math.max(A.length, B.length); i++) {
    const d = (A[i] || 0) - (B[i] || 0);
    if (d) return d;
  }
  return 0;
};
const baseVersion = (v) => (v || '').split('-')[0].split('+')[0].trim();
const estStable = (v) => /^[0-9]+(\.[0-9]+)*$/.test(baseVersion(v));
const prefixe = (v) => (v.match(/^[\^~>=<]*/) || [''])[0];
const num = (v) => v.replace(/^[\^~>=<\s*v]*/, '').trim();
const plusRecent = (latest, current) => {
  const L = baseVersion(num(latest)), C = baseVersion(num(current));
  return estStable(L) && estStable(C) && cmp(L, C) > 0;
};
const typeMaj = (latest, current) => {
  const L = pad(baseVersion(num(latest))), C = pad(baseVersion(num(current)));
  if ((L[0] || 0) > (C[0] || 0)) return 'majeure';
  if ((L[1] || 0) > (C[1] || 0)) return 'mineure';
  return 'correction';
};

// --- registres ---
async function npmLatest(nom) {
  try {
    const r = await this.helpers.httpRequest({ url: `https://registry.npmjs.org/${nom}/latest`, json: true });
    return r.version || null;
  } catch { return null; }
}
const nomPyPi = (n) => n.toLowerCase().replace(/[-_.]+/g, '-');
async function pypiLatest(nom) {
  try {
    const r = await this.helpers.httpRequest({ url: `https://pypi.org/pypi/${encodeURIComponent(nomPyPi(nom))}/json`, json: true });
    return r.info && r.info.version ? r.info.version : null;
  } catch { return null; }
}
const parLots = async (items, taille, fn) => {
  const out = [];
  for (let i = 0; i < items.length; i += taille) {
    out.push(...await Promise.all(items.slice(i, i + taille).map(fn)));
    await sleep(100);
  }
  return out;
};

// --- parsing des fichiers de dépendances ---
function parseRequirements(texte) {
  const deps = [];
  for (const ligne of texte.split('\n')) {
    const l = ligne.trim();
    if (!l || l.startsWith('#') || l.startsWith('-')) continue;
    const m = l.match(/^([A-Za-z0-9_.\-]+(\[[^\]]+\])?)\s*(===|==|~=|>=|>)\s*([0-9][^\s,;]*)/);
    if (m) deps.push({ nom: m[1].replace(/\[[^\]]+\]/, ''), current: m[4], brut: l, section: 'requirements.txt' });
  }
  return deps;
}
function parsePackageJson(texte) {
  let pkg;
  try { pkg = JSON.parse(texte); } catch { return []; }
  const deps = [];
  for (const section of ['dependencies', 'devDependencies']) {
    for (const [nom, v] of Object.entries(pkg[section] || {})) {
      if (!num(v)) continue;
      deps.push({ nom, current: v, section });
    }
  }
  return deps;
}

// --- exécution ---
const aujourdhui = new Date().toISOString().slice(0, 10);
const nomBranche = `deps/maj-auto-${aujourdhui}`;
const lignes = [];
const stats = { branches: 0, prs: 0, aJour: 0, sansDeps: 0, erreurs: 0 };

let repos;
try {
  repos = (await req({ url: `${API}/user/repos?per_page=100&sort=pushed&affiliation=owner,collaborator`, json: true }))
    .filter((r) => !r.archived && !r.fork);
} catch (e) {
  return [{ json: { text: '⚠️ Dépendances GitHub — échec de la liste des repos : ' + String(e.message || e) } }];
}

for (const repo of repos) {
  const full = repo.full_name;
  const entree = { repo: repo.name, full, maj: [], commit: false, note: '' };
  try {
    // fichiers de dépendances à la racine (1 appel)
    let tree;
    try {
      tree = await req({ url: `${API}/repos/${full}/git/trees/${repo.default_branch}?recursive=1`, json: true });
    } catch (e) {
      entree.note = 'arbre inaccessible (' + (e.statusCode || '?') + ')';
      lignes.push(entree); stats.erreurs++; continue;
    }
    const blobs = (tree.tree || []).filter((t) => t.type === 'blob' && !t.path.includes('/'));
    const fichiers = blobs.filter((t) => ['package.json', 'requirements.txt'].includes(t.path));
    if (!fichiers.length) { lignes.push(entree); entree.note = 'aucun fichier de dépendances'; stats.sansDeps++; continue; }

    // parse + dernières versions
    let deps = [];
    for (const f of fichiers) {
      try {
        const raw = await this.helpers.httpRequest({
          url: `https://raw.githubusercontent.com/${full}/${repo.default_branch}/${f.path}`,
          headers: { Authorization: CONFIG.githubToken, 'User-Agent': 'n8n-deps-weekly' }, json: false,
        });
        const texte = getTexte(raw);
        deps.push(...(f.path === 'package.json' ? parsePackageJson(texte) : parseRequirements(texte))
          .map((d) => ({ ...d, fichier: f.path, sha: f.sha })));
      } catch { /* fichier illisible → ignoré */ }
    }
    deps = deps.slice(0, CONFIG.maxPkgsParRepo);
    const avecLatest = await parLots(deps, 5, async (d) => {
      const latest = d.fichier === 'package.json' ? await npmLatest.call(this, d.nom) : await pypiLatest.call(this, d.nom);
      return { ...d, latest };
    });
    entree.maj = avecLatest.filter((d) => d.latest && plusRecent(d.latest, d.current));
    entree.nomsMaj = entree.maj.map((d) => `${d.nom} ${num(d.current)}→${baseVersion(d.latest)}`).join(', ');

    if (!entree.maj.length) {
      const nonResolus = avecLatest.filter((d) => !d.latest).length;
      if (!avecLatest.length) entree.note = 'aucune version épinglée à vérifier';
      else if (nonResolus === avecLatest.length) entree.note = `${avecLatest.length} paquets non résolus (registre ?)`;
      else entree.note = 'à jour';
      lignes.push(entree); stats.aJour++; continue;
    }

    // branche déjà présente ? (run précédent non fusionné)
    try {
      await req({ url: `${API}/repos/${full}/branches/${encodeURIComponent(nomBranche)}`, json: true });
      // branche déjà là : y a-t-il déjà une PR ouverte ?
      let prExistante = null;
      try {
        const prs = await req({ url: `${API}/repos/${full}/pulls?state=open&head=${encodeURIComponent(full)}:${encodeURIComponent(nomBranche)}`, json: true });
        if (prs.length) prExistante = prs[0].html_url;
      } catch { /* ignore */ }
      if (prExistante) {
        entree.note = `branche et PR déjà ouvertes — ${prExistante}`;
        lignes.push(entree); continue;
      }
      // branche déjà là mais pas de PR ouverte -> ouvrir la PR maintenant
      const pr2 = await req({
        url: `${API}/repos/${full}/pulls`, method: 'POST', json: true,
        body: {
          title: `deps: mise à jour automatique des dépendances (${aujourdhui})`,
          head: nomBranche, base: repo.default_branch,
          body: `Mise à jour automatique des dépendances (workflow n8n, hebdomadaire).\n\n`
            + `Branch : \`${nomBranche}\` → \`${repo.default_branch}\`. Aucun merge automatique : à relire.`,
        },
      });
      entree.prUrl = pr2.html_url;
      entree.note = `PR ouverte sur la branche existante — ${pr2.html_url}`;
      lignes.push(entree); stats.prs++; stats.branches++; continue;
    } catch { /* 404 = la branche n'existe pas, on continue */ }

    // tête de la branche par défaut
    let head;
    try {
      head = await req({ url: `${API}/repos/${full}/branches/${encodeURIComponent(repo.default_branch)}`, json: true });
    } catch (e) {
      entree.note = 'branche par défaut inaccessible';
      lignes.push(entree); stats.erreurs++; continue;
    }
    const headSha = head.commit.sha;
    const baseTree = head.commit.commit.tree.sha;

    // nouveaux contenus
    const parFichier = {};
    for (const d of entree.maj) {
      parFichier[d.fichier] = parFichier[d.fichier] || { deps: [] };
      parFichier[d.fichier].deps.push(d);
    }
    const arbre = [];
    for (const [fichier, info] of Object.entries(parFichier)) {
      let contenu = null;
      if (fichier === 'package.json') {
        const raw = await this.helpers.httpRequest({
          url: `https://raw.githubusercontent.com/${full}/${repo.default_branch}/${fichier}`,
          headers: { Authorization: CONFIG.githubToken, 'User-Agent': 'n8n-deps-weekly' }, json: false,
        });
        contenu = getTexte(raw);
        const pkg = JSON.parse(contenu);
        for (const d of info.deps) {
          for (const section of ['dependencies', 'devDependencies']) {
            if (pkg[section] && pkg[section][d.nom] !== undefined) {
              pkg[section][d.nom] = prefixe(d.current) + baseVersion(d.latest);
            }
          }
        }
        contenu = JSON.stringify(pkg, null, 2) + '\n';
      } else {
        const raw = await this.helpers.httpRequest({
          url: `https://raw.githubusercontent.com/${full}/${repo.default_branch}/${fichier}`,
          headers: { Authorization: CONFIG.githubToken, 'User-Agent': 'n8n-deps-weekly' }, json: false,
        });
        const lignesTxt = getTexte(raw).split('\n');
        const remplace = new Map(info.deps.map((d) => [d.brut || d.nom, d]));
        contenu = lignesTxt.map((l) => {
          const lTrim = l.trim();
          if (remplace.has(lTrim)) {
            const d = remplace.get(lTrim);
            return l.replace(/([=<>~]+\s*)[0-9][^\s,;]*/, `$1${baseVersion(d.latest)}`);
          }
          return l;
        }).join('\n');
      }
      // blob → 1 appel
      const blob = await req({
        url: `${API}/repos/${full}/git/blobs`, method: 'POST', json: true,
        body: { content: contenu, encoding: 'utf-8' },
      });
      arbre.push({ path: fichier, mode: '100644', type: 'blob', sha: blob.sha });
    }

    // arbre + commit + branche (3 appels)
    const nouveauTree = await req({
      url: `${API}/repos/${full}/git/trees`, method: 'POST', json: true,
      body: { base_tree: baseTree, tree: arbre },
    });
    const nomsMaj = entree.maj.map((d) => `${d.nom} ${num(d.current)}→${baseVersion(d.latest)}`).join(', ');
    const commit = await req({
      url: `${API}/repos/${full}/git/commits`, method: 'POST', json: true,
      body: { message: `chore(deps): mise à jour automatique des dépendances\n\n${nomsMaj}`, tree: nouveauTree.sha, parents: [headSha] },
    });
    await req({
      url: `${API}/repos/${full}/git/refs`, method: 'POST', json: true,
      body: { ref: `refs/heads/${nomBranche}`, sha: commit.sha },
    });
    // PR automatique depuis la branche vers la branche par défaut
    const titrePr = `deps: mise à jour automatique des dépendances (${aujourdhui})`;
    const corpsPr = `Mise à jour automatique des dépendances (workflow n8n, hebdomadaire).\n\n`
      + entree.nomsMaj.split(', ').map((l) => `- [ ] ${l}`).join('\n')
      + `\n\nBranch : \`${nomBranche}\` → \`${repo.default_branch}\`. Aucun merge automatique : à relire.`;
    try {
      const pr = await req({
        url: `${API}/repos/${full}/pulls`, method: 'POST', json: true,
        body: { title: titrePr, head: nomBranche, base: repo.default_branch, body: corpsPr },
      });
      entree.prUrl = pr.html_url;
      entree.commit = true;
      stats.prs++;
    } catch (ePr) {
      entree.prUrl = null;
      entree.note = 'branche créée mais PR en échec : ' + String(ePr.message || ePr);
    }
    lignes.push(entree); stats.branches++;
    await sleep(200);
  } catch (e) {
    entree.note = 'erreur: ' + String(e.message || e);
    lignes.push(entree); stats.erreurs++;
  }
}

// --- récap Telegram ---
const parties = [`🔧 Dépendances GitHub — ${aujourdhui}`];
for (const e of lignes) {
  if (e.commit) {
    const parType = {};
    for (const d of e.maj) (parType[typeMaj(d.latest, d.current)] = parType[d.maj ? typeMaj(d.latest, d.current) : ''] || []).push(d);
    const majeures = (parType['majeure'] || []), mineures = (parType['mineure'] || []), corrections = (parType['correction'] || []);
    parties.push(`🌿 ${e.repo} — PR ouverte : ${e.prUrl || '⚠️ échec PR, branche ' + nomBranche + ' créée'} (${e.maj.length} maj : ${majeures.length} majeures, ${mineures.length} mineures, ${corrections.length} corrections)`);
    const detail = [...majeures, ...mineures, ...corrections].slice(0, CONFIG.maxDetail)
      .map((d) => `   • ${d.nom} ${num(d.current)} → ${baseVersion(d.latest)}`).join('\n');
    if (detail) parties.push(detail + (e.maj.length > CONFIG.maxDetail ? `\n   … (+${e.maj.length - CONFIG.maxDetail})` : ''));
  } else if (e.maj && e.maj.length) {
    parties.push(`↩️ ${e.repo} — ${e.note}`);
  } else if (e.note) {
    parties.push(`➖ ${e.repo} — ${e.note}`);
  } else {
    parties.push(`✅ ${e.repo} — à jour`);
  }
}
parties.push(`—\nPRs créées : ${stats.prs} | Branches sans PR : ${stats.branches - stats.prs} | À jour : ${stats.aJour} | Sans deps : ${stats.sansDeps} | Erreurs : ${stats.erreurs}`);
parties.push('Les PRs ne touchent pas main — à relire et fusionner sur GitHub.');

console.log('DEPS-DEBUG ' + JSON.stringify({ stats, lignes }));
return [{ json: { text: parties.join('\n').slice(0, 3800) } }];
